// Chapter practice questions are based on the corresponding chapters of the
// uploaded 2026 New Jersey Driver Manual. Page references are printed page numbers.

const CHAPTER_CONFIG = {
  1: { title: 'The New Jersey Driver License System', short: 'Driver License System', pages: '4–27' },
  2: { title: 'New Jersey Driver Testing', short: 'Driver Testing', pages: '30–37' },
  3: { title: 'Driver Responsibility', short: 'Driver Responsibility', pages: '40–59' },
  4: { title: 'Safe Driving Rules and Regulations', short: 'Safe Driving Rules', pages: '62–87' },
  5: { title: 'Defensive Driving', short: 'Defensive Driving', pages: '90–111' },
  6: { title: 'Drinking, Drugs, and Health', short: 'Drinking, Drugs & Health', pages: '114–119' },
  7: { title: 'Driver Privileges and Penalties', short: 'Privileges & Penalties', pages: '122–140' },
  8: { title: 'Sharing the Road with Others', short: 'Sharing the Road', pages: '144–155' },
  9: { title: 'Vehicle Information', short: 'Vehicle Information', pages: '158–161' }
};

const chapterCounters = {};

function chapterQuestion(chapter, page, topic, q, a, c, why) {
  chapterCounters[chapter] = (chapterCounters[chapter] || 0) + 1;

  return {
    id: `chapter-${chapter}-${String(chapterCounters[chapter]).padStart(2, '0')}`,
    topic,
    page,
    q,
    a,
    c,
    why
  };
}

