// Fail early during development if a chapter is incomplete or malformed.
for (const chapterNumber of Object.keys(CHAPTER_CONFIG)) {
  const questions = CHAPTER_BANKS[chapterNumber];

  if (!questions || questions.length !== 30) {
    throw new Error(
      `Chapter ${chapterNumber} must contain exactly 30 questions; found ${questions ? questions.length : 0}.`
    );
  }

  for (const question of questions) {
    if (question.a.length !== 4 || question.c < 0 || question.c > 3) {
      throw new Error(`Invalid answer set in ${question.id}.`);
    }
  }
}